import React, { useState, useEffect } from 'react';
import { getRandomQuestion } from '../../services/dataService';
import './GameMode.css';

// ... 在文件开头附近更新这些文本 ...

<div className="mode-selector">
  <button
    onClick={() => setMode('practice')}
    className={mode === 'practice' ? 'active' : ''}
  >
    Practice Mode
  </button>
  <button
    onClick={() => setMode('competition')}
    className={mode === 'competition' ? 'active' : ''}
  >
    Competition Mode
  </button>
</div>

{mode === 'competition' && (
  <div className="game-stats">
    <div>Time: {timeLeft}s</div>
    <div>Score: {score}</div>
  </div>
)}

<button onClick={startGame} className="start-button">
  Start Game
</button>

// ... 更新提示信息 ...
alert(isCorrect ?
  `Correct!\n${question.explanation}` :
  `Wrong. The correct answer is ${question.correctAnswer}\n${question.explanation}`
);

// ... 更新游戏结束提示 ...
alert(`Game Over!\nFinal Score: ${score}\nAccuracy: ${Math.round(stats.correct/stats.total*100)}%`);

const GameMode = () => {
  const [mode, setMode] = useState('practice'); // 'practice' 或 'competition'
  const [question, setQuestion] = useState(null);
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(60);
  const [gameActive, setGameActive] = useState(false);
  const [stats, setStats] = useState({ correct: 0, total: 0 });

  // 获取新问题
  const getNewQuestion = () => {
    const newQuestion = getRandomQuestion();
    setQuestion(newQuestion);
  };

  // 处理答案
  const handleAnswer = (selectedEffect) => {
    if (!question) return;

    const isCorrect = selectedEffect === question.correctAnswer;
    
    if (mode === 'competition') {
      setScore(prev => prev + (isCorrect ? 10 : -5));
    }

    setStats(prev => ({
      correct: prev.correct + (isCorrect ? 1 : 0),
      total: prev.total + 1
    }));

    // 显示答案解释
    alert(isCorrect ? 
      `正确！\n${question.explanation}` : 
      `错误。正确答案是 ${question.correctAnswer}\n${question.explanation}`
    );

    getNewQuestion();
  };

  // 开始新游戏
  const startGame = () => {
    setGameActive(true);
    setScore(0);
    setStats({ correct: 0, total: 0 });
    if (mode === 'competition') {
      setTimeLeft(60);
    }
    getNewQuestion();
  };

  // 竞赛模式计时器
  useEffect(() => {
    let timer;
    if (mode === 'competition' && gameActive && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            setGameActive(false);
            clearInterval(timer);
            alert(`游戏结束！\n最终得分：${score}\n正确率：${Math.round(stats.correct/stats.total*100)}%`);
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [mode, gameActive, timeLeft]);

  return (
    <div className="game-container">
      <div className="mode-selector">
        <button 
          onClick={() => setMode('practice')} 
          className={mode === 'practice' ? 'active' : ''}
        >
          训练模式
        </button>
        <button 
          onClick={() => setMode('competition')} 
          className={mode === 'competition' ? 'active' : ''}
        >
          竞赛模式
        </button>
      </div>

      {!gameActive ? (
        <button onClick={startGame} className="start-button">
          开始游戏
        </button>
      ) : (
        <div className="game-area">
          {mode === 'competition' && (
            <div className="game-stats">
              <div>时间：{timeLeft}秒</div>
              <div>得分：{score}</div>
            </div>
          )}
          
          // ... existing code ...

{question && (
  <div className="question-area">
    <h3>Question:</h3>
    {question.questionType === 'policy' ? (
      <div className="question-content">
        <div className="question-policy">
          <strong>Policy:</strong><br />
          {question.policy}
        </div>
        <div className="question-target">
          <strong>Effect on:</strong><br />
          {question.variable}
        </div>
      </div>
    ) : (
      <div className="question-content">
        <div className="question-event">
          <strong>Event:</strong><br />
          {question.event}
        </div>
        <div className="question-target">
          <strong>Effect on:</strong><br />
          {question.curve} in {question.diagram}
        </div>
      </div>
    )}

    <div className="answer-buttons">
      <button onClick={() => handleAnswer('increase')}>
        Increase
      </button>
      <button onClick={() => handleAnswer('decrease')}>
        Decrease
      </button>
    </div>
  </div>
)}

<div className="stats">
  Accuracy: {stats.total > 0 ? Math.round(stats.correct/stats.total*100) : 0}%
  ({stats.correct}/{stats.total})
</div>

// ... existing code ...
        </div>
      )}
    </div>
  );
};

export default GameMode;
